WITH p AS (SELECT coalesce(%s::text,'') ma_khuon,coalesce(%s::text,'') ma_sp,coalesce(%s::text,'') trang_thai,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' all_branch FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT row_number() OVER(ORDER BY h.ma_khuon,d.ln) stt,h.ma_khuon,h.ten_khuon,d.ln,d.ma_sp,v.ten_vt,d.id_cap,d.chu_ki,d.chinh_phu,d.cavity,h.so_cavity,h.tong_so_shot,h.tinh_trang_khuon,h.vi_tri_khuon,h.ngay,h.ngay_bh,h.ngay_sx_cuoi_cung,h.status,count(*) OVER() total FROM public.dmhosokhuon h LEFT JOIN public.dmhosokhuonsp d ON d.ma_khuon=h.ma_khuon LEFT JOIN public.dmvt v ON v.ma_vt=d.ma_sp CROSS JOIN s WHERE s.ok IS NOT NULL AND (s.ma_khuon='' OR h.ma_khuon=ANY(string_to_array(s.ma_khuon,','))) AND (s.ma_sp='' OR d.ma_sp=ANY(string_to_array(s.ma_sp,','))) AND (s.trang_thai='' OR h.status=s.trang_thai) AND (s.all_branch OR coalesce(h.branch_code,'')='' OR EXISTS(SELECT 1 FROM unnest(string_to_array(s.bs,',')) x WHERE x=ANY(string_to_array(h.branch_code,',')))) ORDER BY h.ma_khuon,d.ln LIMIT (SELECT lim FROM p);
